describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents in bracket", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -10,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            9.9,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with zero total weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", undefined, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("selects correct bracket at boundary (exactly upToGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 500, 1)]; // 500g — exactly first bracket
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects next bracket when just over boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 501, 1)]; // 501g — second bracket
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 5000, 1)]; // exactly 5000g
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("uses overflow cost when exceeding all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine("a", 5001, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(2000);
    });

    it("uses last bracket cost as default overflow when overflowCostCents not specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 10000, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("handles unsorted brackets (sorts internally)", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      const lines = [makeLine("a", 700, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)]; // 300*2+200 = 800g
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500 };

describe("Cart — line management", () => {
  it("add increases item count", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantities for same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws on non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("add throws on non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add throws on negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true and removes existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity with 0 removes the item", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("missing", 1)).toThrow();
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const snap = cart.snapshot();
    // Mutating snapshot shouldn't affect cart
    (snap as any)[0].quantity = 99;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart — pricing pipeline", () => {
  it("subtotal is sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4500);
  });

  it("empty cart has all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("applies discount via injected policy", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 2); // subtotal 2000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500);
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(2000);
  });

  it("clamps discount to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(150),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
    cart.add(productA, 2); // subtotal 2000, discount 500, discounted = 1500
    const totals = cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1500, "US-CA");
    expect(totals.taxCents).toBe(150);
  });

  it("shipping receives discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(800),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(productA, 1); // subtotal 1000, discount 200, discounted = 800
    const totals = cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
    expect(totals.shippingCents).toBe(800);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();
    // discounted = 900, tax = 72, shipping = 500, total = 900+72+500 = 1472
    expect(totals.totalCents).toBe(1472);
  });

  it("defaults to US region", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("uses custom region", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

