toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 for any taxable amount", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
  });

  it("returns 0 for zero taxable", () => {
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 regardless of region", () => {
    expect(calc.computeTaxCents(5000, "FR")).toBe(0);
    expect(calc.computeTaxCents(5000, "JP")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative default rate", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects default rate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN default rate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects invalid rate in rates map", () => {
      expect(() => new RegionalTaxCalculator({ US: -0.05 })).toThrow(RangeError);
    });

    it("rejects rate > 1 in rates map", () => {
      expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
    });

    it("accepts valid rates", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 0.0875, FR: 0.2 }, 0.1),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, "US-OR": 0, GB: 0.2 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // 8.75% of 10000 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 10000 = 500
      expect(calc.computeTaxCents(10000, "DE")).toBe(500);
    });

    it("returns 0 for zero-rate region", () => {
      expect(calc.computeTaxCents(10000, "US-OR")).toBe(0);
    });

    it("rounds down to nearest cent", () => {
      // 20% of 999 = 199.8 → 199
      expect(calc.computeTaxCents(999, "GB")).toBe(199);
    });

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-1000, "US-CA")).toBe(0);
    });

    it("handles default rate of 0", () => {
      const zeroDefault = new RegionalTaxCalculator({ US: 0.1 });
      expect(zeroDefault.computeTaxCents(1000, "XX")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for non-positive taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("computes tax using async rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8% of 5000 = 400
    expect(await calc.computeTaxCents(5000, "US-TX")).toBe(400);
    expect(provider.getRate).toHaveBeenCalledWith("US-TX");
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.07),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 7% of 999 = 69.93 → 69
    expect(await calc.computeTaxCents(999, "US")).toBe(69);
  });

  it("throws RangeError for rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network down")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow("network down");
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 500 }, quantity: 1 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(900);
  });

  it("treats undefined weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

