toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
    });

    it("accepts valid params without threshold", () => {
      expect(() => new FlatShippingCalculator(500)).not.toThrow();
    });

    it("accepts valid params with threshold", () => {
      expect(() => new FlatShippingCalculator(500, 5000)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns flat fee for non-empty cart without threshold", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 2000)).toBe(799);
    });

    it("returns flat fee when subtotal is below threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(500);
    });

    it("returns 0 when subtotal meets threshold exactly", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 10000)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents in bracket", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -10,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            9.9,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with zero total weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", undefined, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("selects correct bracket at boundary (exactly upToGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 500, 1)]; // 500g — exactly first bracket
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects next bracket when just over boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 501, 1)]; // 501g — second bracket
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 5000, 1)]; // exactly 5000g
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("uses overflow cost when exceeding all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine("a", 5001, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(2000);
    });

    it("uses last bracket cost as default overflow when overflowCostCents not specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 10000, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("handles unsorted brackets (sorts internally)", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      const lines = [makeLine("a", 700, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)]; // 300*2+200 = 800g
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });
  });
});

